UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Bir [[amber]]EDATTAN[[/amber]] hemen sonra gelen fiil HER ZAMAN [[q]]-ing[[/q]] formunda olur, asla [[bad]]\"to + yalın fiil\"[[/bad]] gelmez:", "items": [{"heading": "Edattan Sonra Her Zaman -ing", "body": [{"type": "text", "text": "Bir [[amber]]EDATTAN[[/amber]] (in, on, at, about, for, of, without, before, after, by vb.) hemen sonra gelen fiil HER ZAMAN [[q]]-ing[[/q]] (gerund) formunda olur, asla [[bad]]\"to + yalın fiil\"[[/bad]] gelmez."}, {"type": "example_check", "correct": "interested in learning", "wrong_note": "\"interested in to learn\" YANLIŞTIR"}]}, {"heading": "\"to\" Edat Olunca Tuzağı", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "En sık tuzak \"to\"nun bir EDAT olarak kullanıldığı sabit kalıplarda ortaya çıkar — [[q]]\"look forward to\"[[/q]], [[q]]\"be used to\"[[/q]], [[q]]\"object to\"[[/q]], [[q]]\"in addition to\"[[/q]], [[q]]\"when it comes to\"[[/q]] gibi kalıplarda bu \"to\" bir infinitive belirteci DEĞİL, bir EDATTIR, bu yüzden ardından -ing gelir."}, {"type": "example_check", "correct": "I look forward to seeing you", "wrong_note": "\"I look forward to see you\" YANLIŞTIR"}], "warning_text": "Sınavda boşluktan hemen ÖNCE bir edat (özellikle bu kalıplardaki \"to\") görürsen, şıklar arasında \"to + yalın fiil\" olan her seçenek otomatik olarak elenir."}], "examples": [{"sentence": "She is really looking forward to seeing her family again after two years abroad.", "answer_word": "to seeing", "reasoning": "\"look forward to\" kalıbındaki \"to\" bir edattır, ardından -ing gelir → doğru cevap [[right]]\"to seeing\"[[/right]]dir; [[wrong]]\"to see\"[[/wrong]] burada yaygın bir hatadır ve yanlıştır."}, {"sentence": "He apologized for being late to the meeting without giving any real explanation.", "answer_word": "for being", "reasoning": "\"apologize for\" kalıbındaki \"for\" bir edattır ve ardından -ing gelir → doğru cevap [[right]]\"for being\"[[/right]]dir; [[wrong]]\"for to be\"[[/wrong]] ya da [[wrong]]\"to be\"[[/wrong]] gramer olarak burada mümkün değildir."}, {"sentence": "The union insisted on conducting a full investigation before any employees were dismissed.", "answer_word": "on conducting", "reasoning": "\"insist on\" kalıbındaki \"on\" bir edattır, ardından -ing gelir → doğru cevap [[right]]\"on conducting\"[[/right]]dir; [[wrong]]\"to conduct\"[[/wrong]] burada edat kuralını ihlal ettiği için yanlıştır."}, {"sentence": "You can't complete this assignment without reading the instructions carefully first.", "answer_word": "reading", "reasoning": "\"without\" bir edattır ve ardından -ing gelir → doğru cevap [[right]]\"reading\"[[/right]]dir; [[wrong]]\"to read\"[[/wrong]] ya da yalın [[wrong]]\"read\"[[/wrong]] burada edattan sonra kesinlikle gelemez."}]}$tagbd$::jsonb WHERE id = 'c0d0bfe9-a8ba-4b33-a45a-b81cd7863d84';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Önce boşluğun cümlede HANGİ GÖREVİ üstlendiğine bak (sıfat mı, zarf mı, isim mi), sonra köke uygun eki ekle:", "items": [{"heading": "Boşluğun Görevini Belirle, Sonra Eki Seç", "badge": "Kelime Türetme", "sub_rules": [{"condition": "Boşluk bir [[amber]]İSİM[[/amber]] gerektiriyorsa (-tion, -ness, -ment, -ity gibi ekler):", "from": "decide", "to": "decision"}, {"condition": "Boşluk bir [[amber]]SIFAT[[/amber]] gerektiriyorsa (-ful, -less, -able, -ive; un-/in-/dis-/im- olumsuzluk ekleri):", "from": "responsibility", "to": "irresponsible"}, {"condition": "Boşluk bir [[amber]]ZARF[[/amber]] gerektiriyorsa (-ly eki):", "from": "graceful", "to": "gracefully"}]}, {"heading": "Collocation: Doğal Kelime Eşleşmeleri", "body": [{"type": "text", "text": "Collocation sorularında tek tek kelimelerin anlamından çok, hangi kelimelerin [[amber]]DOĞAL OLARAK[[/amber]] birlikte kullanıldığına bak: [[ok]]\"make a decision\"[[/ok]] doğrudur ama [[bad]]\"do a decision\"[[/bad]] İngilizcede kullanılmaz — bu bir gramer kuralı değil, YERLEŞİK bir alışkanlıktır ve ezbere dayanır."}]}], "examples": [{"sentence": "The committee's decision to postpone the project disappointed many investors.", "answer_word": "decision", "reasoning": "Boşluk \"The committee's\" iyelik ekinden sonra bir İSİM gerektirdiği için doğru cevap [[right]]\"decision\"[[/right]]dır; [[wrong]]\"decide\"[[/wrong]] (fiil) ya da [[wrong]]\"decisive\"[[/wrong]] (sıfat) bu konumda kullanılamaz."}, {"sentence": "It is irresponsible to ignore the long-term environmental effects of such industrial projects.", "answer_word": "irresponsible", "reasoning": "Boşluk \"It is ___ to\" kalıbında bir SIFAT gerektirdiği için doğru cevap [[right]]\"irresponsible\"[[/right]]dır ([[wrong]]\"responsibility\"[[/wrong]] isim, [[wrong]]\"irresponsibly\"[[/wrong]] zarf olduğu için elenir); olumsuzluk öneki \"ir-\" burada \"responsible\" kökünün \"r\" ile başlamasına uyum sağlar."}, {"sentence": "She performed the complicated dance routine gracefully in front of thousands of spectators.", "answer_word": "gracefully", "reasoning": "Boşluk \"performed\" (fiil) eylemini nitelediği için bir ZARF gerekir → doğru cevap [[right]]\"gracefully\"[[/right]]dir; [[wrong]]\"graceful\"[[/wrong]] (sıfat) ya da [[wrong]]\"grace\"[[/wrong]] (isim) bir fiili nitelendiremediği için burada kullanılamaz."}, {"sentence": "Despite the tight deadline, the team decided to make every effort to deliver the project on time.", "answer_word": "make", "reasoning": "İngilizcede \"effort\" kelimesiyle doğal eşleşen fiil [[right]]\"make\"[[/right]]tir ([[q]]\"make an effort\"[[/q]]) — [[wrong]]\"do an effort\"[[/wrong]] bir gramer hatası değil ama YERLEŞİK olmayan bir ifadedir, bu yüzden collocation sorularında hangi fiilin hangi isimle ALIŞILAGELMİŞ şekilde kullanıldığına bakmak gerekir."}]}$tagbd$::jsonb WHERE id = 'd9a28662-cb55-4ccc-8ae0-139f902f12b0';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]wish[[/q]] ve [[q]]if only[[/q]], gerçek durumun TERSİNİ dilemek için kullanılır ve fiil zamanı gerçek zamandan [[dark]]BİR BASAMAK GERİYE[[/dark]] kayar:", "items": [{"heading": "Zaman Bir Basamak Geri Kayar", "badge": "wish / if only", "sub_rules": [{"condition": "[[amber]]ŞİMDİKİ[[/amber]] bir durumdan memnuniyetsizlik için:", "from": "PRESENT", "to": "wish + PAST SIMPLE"}, {"condition": "[[amber]]GEÇMİŞE[[/amber]] dönük bir pişmanlık için:", "from": "PAST", "to": "wish + PAST PERFECT"}, {"condition": "[[amber]]GELECEKTE[[/amber]] bir şeyin değişmesini dilemek / rahatsızlık için:", "from": "will", "to": "wish + WOULD"}]}, {"heading": "\"be\" Fiili ve Yasak Yardımcılar", "body": [{"type": "text", "text": "\"be\" fiili için her özneyle [[q]]\"were\"[[/q]] kullanılır, [[bad]]\"was\"[[/bad]] değil ([[b]]\"I wish I knew the answer\"[[/b]], [[b]]\"I wish I were taller\"[[/b]])."}, {"type": "text", "text": "[[bad]]\"will/can/must\"[[/bad]] gibi yapıları doğrudan wish'ten sonra kullanmak her zaman yanlıştır."}]}], "examples": [{"sentence": "I wish I were taller so I could reach the top shelf.", "answer_word": "were", "reasoning": "Şu anki bir durumdan (boyunun kısa olması) memnuniyetsizlik anlatıldığı için doğru cevap [[right]]\"were\"[[/right]]dir, [[wrong]]\"am\"[[/wrong]] veya [[wrong]]\"will be\"[[/wrong]] değildir."}, {"sentence": "If only I had apologized to her before she left the country last year.", "answer_word": "had apologized", "reasoning": "Geçmişte yapılmamış bir eylem için pişmanlık anlatıldığı için doğru cevap [[right]]\"had apologized\"[[/right]]tır (past perfect); [[wrong]]\"apologized\"[[/wrong]] (sadece past simple) burada yanlıştır çünkü dilek şimdiki değil geçmiş bir duruma yöneliktir."}, {"sentence": "I wish I hadn't eaten so much at the party; I feel sick now.", "answer_word": "hadn't eaten", "reasoning": "Geçmişte yapılmış, pişmanlık duyulan bir eylem anlatıldığı için doğru cevap [[right]]\"hadn't eaten\"[[/right]]tır (past perfect); [[wrong]]\"didn't eat\"[[/wrong]] burada yanlıştır çünkü dilek şimdiki bir durumdan değil geçmişteki bir eylemden duyulan pişmanlıktır."}, {"sentence": "If only the neighbors would turn down that music; it's impossible to concentrate.", "answer_word": "would turn down", "reasoning": "Başkasının DEVAM EDEN davranışından duyulan rahatsızlık anlatıldığı için doğru cevap [[right]]\"would turn down\"[[/right]]tır; [[wrong]]\"turned down\"[[/wrong]] (past simple) burada yanlıştır çünkü bu yapı bir pişmanlığı değil bir ısrar/rahatsızlığı anlatır."}]}$tagbd$::jsonb WHERE id = 'e0308451-bc6b-48e5-9b8d-9e3a0d78ed8b';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "when, while, before, after, until, as soon as, by the time gibi bağlaçlarla kurulan ZAMAN cümleciklerinde, olay gelecekte gerçekleşecek olsa BİLE [[bad]]\"will\"[[/bad]] KULLANILMAZ:", "items": [{"heading": "Zaman Cümleciklerinde \"will\" Yasak", "body": [{"type": "text", "text": "[[q]]when, while, before, after, until, as soon as, by the time[[/q]] gibi bağlaçlarla kurulan ZAMAN cümleciklerinde, anlatılan olay gelecekte gerçekleşecek olsa BİLE [[bad]]\"will\"[[/bad]] KULLANILMAZ."}, {"type": "text", "text": "Bunun yerine [[q]]Present Simple[[/q]] (olay tek seferlik/eşzamanlı ise) veya [[q]]Present Perfect[[/q]] (zaman cümleciğindeki eylem ana cümledeki eylemden ÖNCE tamamlanmış olacaksa, özellikle \"by the time\" ve \"after\" ile) kullanılır."}]}, {"heading": "\"will\" Sadece Ana Cümlede", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "[[q]]\"will\"[[/q]] sadece ANA cümlede (zaman cümleciği olmayan kısımda) kullanılabilir."}, {"type": "example_check", "correct": "I will call you as soon as I finish the meeting", "wrong_note": "\"as soon as I will finish\" YANLIŞTIR"}], "warning_text": "Bir şıkta zaman bağlacından hemen sonra \"will\" görürsen bu şık YDS'de neredeyse her zaman yanlıştır."}], "examples": [{"sentence": "By the time she arrives at the airport, the plane will have already taken off.", "answer_word": "arrives", "reasoning": "\"By the time\" ile kurulan zaman cümleciğinde \"will\" kullanılmaz, Present Simple yeterlidir → doğru cevap [[right]]\"arrives\"[[/right]]tir; [[wrong]]\"will arrive\"[[/wrong]] tuzaktır."}, {"sentence": "I will call you as soon as I finish the meeting.", "answer_word": "finish", "reasoning": "Burada ana cümlede zaten \"will\" var ([[b]]\"I will call\"[[/b]]), ama \"as soon as\" ile başlayan zaman cümleciğinde yine \"will\" kullanılamaz → doğru cevap [[right]]\"finish\"[[/right]]tir, [[wrong]]\"will finish\"[[/wrong]] değil — iki \"will\" bir cümlede zaman cümleciğiyle asla bir arada bulunmaz."}, {"sentence": "I'll keep practicing the violin until I master this piece completely.", "answer_word": "master", "reasoning": "\"until\" ile kurulan zaman cümleciğinde gelecek bir eylemden bahsedilse bile \"will\" kullanılmaz, Present Simple yeterlidir → doğru cevap [[right]]\"master\"[[/right]]dır; [[wrong]]\"will master\"[[/wrong]] bu kalıpta klasik bir tuzaktır."}, {"sentence": "While you are waiting for the bus, I'll run into the pharmacy to pick up my prescription.", "answer_word": "are waiting", "reasoning": "\"while\" ile kurulan ve ana cümledeki eylemle EŞZAMANLI süren bir eylem anlatıldığı için doğru cevap Present Continuous [[right]]\"are waiting\"[[/right]]tir; [[wrong]]\"will wait\"[[/wrong]] burada da zaman cümleciğinde \"will\" kullanılamayacağı kuralını ihlal eder."}]}$tagbd$::jsonb WHERE id = '91bc4f15-b79e-4eeb-9fde-90054f934f0e';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "want, tell, ask, expect, allow, encourage gibi fiillerden sonra [[amber]]NESNE[[/amber]] + to-infinitive kalıbı kullanılır, ama [[q]]\"suggest\"[[/q]] ve [[q]]\"recommend\"[[/q]] bu kalıba UYMAZ:", "items": [{"heading": "Fiil + Nesne + to-infinitive Kalıbı", "body": [{"type": "text", "text": "[[q]]want, tell, ask, would like, expect, allow, encourage, remind, warn[[/q]] gibi fiillerden sonra [[amber]]NESNE[[/amber]] (eylemi gerçekleştirecek kişi) + to-infinitive kalıbı kullanılır: [[b]]\"I want you to help me\"[[/b]] (yardım edecek olan: sen, ben değil) — nesne araya MUTLAKA girmelidir."}, {"type": "example_check", "correct": "I want you to help me", "wrong_note": "\"I want to help me\" ya da nesnesiz \"tell to come\" gibi yapılar YANLIŞTIR"}]}, {"heading": "İstisna: \"suggest\" ve \"recommend\"", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "[[q]]\"suggest\"[[/q]] ve [[q]]\"recommend\"[[/q]] bu kalıba [[dark]]UYMAZ[[/dark]] — bu iki fiilden sonra nesne+to-infinitive DEĞİL, [[q]]\"that\"[[/q]] cümleciği ya da doğrudan [[q]]-ing[[/q]] kullanılır."}, {"type": "example_check", "correct": "suggest going / suggest that he go", "wrong_note": "\"suggest him to go\" çok yaygın yapılan ama KESİNLİKLE YANLIŞ olan bir hatadır"}], "warning_text": "Sınavda \"suggest/recommend\" görüp hemen ardından \"nesne + to-infinitive\" içeren bir şık varsa, o şık otomatik olarak elenmelidir."}], "examples": [{"sentence": "The coach always encourages his players to try hard even when the team is losing.", "answer_word": "to try", "reasoning": "\"encourage\" fiili nesne ([[b]]\"his players\"[[/b]]) + to-infinitive kalıbı ister → doğru cevap [[right]]\"to try\"[[/right]]dir; nesnesiz [[wrong]]\"trying\"[[/wrong]] ya da [[wrong]]\"try\"[[/wrong]] burada yanlıştır."}, {"sentence": "The doctor suggested drinking more water every day, but didn't specify an exact amount.", "answer_word": "drinking", "reasoning": "\"suggest\" fiili nesne+to-infinitive kalıbına UYMADIĞI için ardından -ing gelir → doğru cevap [[right]]\"drinking\"[[/right]]dir; [[wrong]]\"him to drink\"[[/wrong]] gibi bir yapı burada yaygın ama yanlış bir hata olurdu."}, {"sentence": "The strict new company policy doesn't allow employees to make personal calls during working hours.", "answer_word": "to make", "reasoning": "\"allow\" fiili de nesne ([[b]]\"employees\"[[/b]]) + to-infinitive kalıbı ister → doğru cevap [[right]]\"to make\"[[/right]]dir; nesnesiz [[wrong]]\"making\"[[/wrong]] burada yanlıştır."}, {"sentence": "The nutritionist recommended eating more vegetables instead of relying on supplements.", "answer_word": "eating", "reasoning": "\"recommend\" fiili nesne+to-infinitive kalıbına UYMADIĞI için ardından -ing gelir → doğru cevap [[right]]\"eating\"[[/right]]dir; [[wrong]]\"people to eat\"[[/wrong]] gibi bir yapı kurmak burada yaygın bir hata olurdu."}]}$tagbd$::jsonb WHERE id = '97810547-d76e-4236-b591-0502859fd43c';
